<?php
/**
 * MarketLens backend configuration.
 *
 * Do not edit this file on the server — create `config.local.php` next to it
 * that returns an array of overrides. It survives redeploys, e.g.:
 *
 *   <?php return ['cron_token' => 'long-random-string', 'twelvedata_key' => 'abc'];
 */
$config = [
    'timezone' => 'Asia/Kolkata',
    'data_dir' => __DIR__ . '/data',

    // Live quotes
    'quote_ttl' => 60,            // seconds a quote is cached
    'history_ttl' => 1800,        // seconds a price-history series is cached
    'max_symbols' => 60,
    'twelvedata_key' => '',       // optional fallback provider (free key at twelvedata.com)

    // IPO tracker
    'ipo_refresh_minutes' => 20,  // if no cron job ran within this window, refresh on request
    'ipo_keep_days' => 120,       // drop IPOs that listed more than N days ago
    'cron_token' => '',           // set to allow https://site/api/cron/update-ipos.php?token=...
    // NSE equity trading holidays (weekdays only). Used for IPO T+3 timeline estimates and to find
    // the last trading day of each week for the weekly index targets. Extend each year.
    'market_holidays' => [
        // 2026 (NSE circular)
        '2026-01-15', '2026-01-26', '2026-03-03', '2026-03-26', '2026-03-31', '2026-04-03', '2026-04-14', '2026-05-01',
        '2026-05-28', '2026-06-26', '2026-09-14', '2026-10-02', '2026-10-20', '2026-11-10', '2026-11-24', '2026-12-25',
    ],
    'market_close' => '15:30',     // NSE / BSE regular session close (IST)
    'weekly_rollover_delay' => 1800, // seconds after the week's last close before targets move to the new week (4:00 pm IST, once closing prices have settled)

    // Grey-market premium sources (HTML tables with an IPO name column and a GMP column).
    'gmp_sources' => [
        ['name' => 'IPO Watch', 'url' => 'https://ipowatch.in/ipo-grey-market-premium-latest-ipo-gmp/'],
        ['name' => 'InvestorGain', 'url' => 'https://www.investorgain.com/report/live-ipo-gmp/331/'],
    ],

    // Upstream hosts (overridable for testing against mocks).
    // Screener
    'screener_ttl' => 120,         // seconds index quotes are cached
    'constituents_ttl' => 86400,   // index member lists change only at rebalancing

    'upstream' => [
        'yahoo' => ['https://query1.finance.yahoo.com', 'https://query2.finance.yahoo.com'],
        'yahoo_cookie' => 'https://fc.yahoo.com',
        'niftyindices' => 'https://www.niftyindices.com',
        'nse' => 'https://www.nseindia.com',
        'twelvedata' => 'https://api.twelvedata.com',
    ],
    'http_timeout' => 12,
];

$local = getenv('ML_CONFIG_LOCAL') ?: __DIR__ . '/config.local.php';
if (is_file($local)) {
    $over = require $local;
    if (is_array($over)) {
        $config = array_replace($config, $over);
    }
}
date_default_timezone_set($config['timezone']);
return $config;
